68: func taskHasChanges(task store.Task) bool {
69: 	if task.WorktreePath == "" || task.BaseRef == "" {
70: 		return true
71: 	}
72: 	cmd := exec.Command("git", "-C", task.WorktreePath, "diff", "--quiet", task.BaseRef+"...HEAD")
73: 	if err := cmd.Run(); err != nil {
74: 		return true
75: 	}
76: 	cmd = exec.Command("git", "-C", task.WorktreePath, "status", "--porcelain")
77: 	status, err := cmd.Output()
